27	// hasReferenceTo returns true if the source node has a reference to the target node.
28	// In other words, if the target node is a dependency of the source node.
29	func hasReferenceTo(source Node, target Node) bool {
30		for _, dep := range source.GetDependencies() {
31			if dep.Name() == target.Name() {
32				return true
33			}
34		}
35		return false
36	}
37	
38	// selfReferencingNode returns true if the given node references itself.
39	func selfReferencingNode(node Node) bool {
40		return hasReferenceTo(node, node)
41	}
42	
43	// isComponent returns true if the given node is a component.
44	func isComponent(node Node) bool {
45		_, ok := node.(*Component)
46		return ok
47	}
48	
49	// mutuallyDependantComponents returns true if the given nodes are components that reference each other.
50	func mutuallyDependantComponents(a Node, b Node) bool {
51		return isComponent(a) &&
52			isComponent(b) &&
53			hasReferenceTo(a, b) &&
54			hasReferenceTo(b, a) &&
55			a.Name() != b.Name()
56	}
57	
58	// bindNode binds a single node in a program. The node's dependencies are bound prior to the node itself; it is an
59	// error for a node to depend--directly or indirectly--upon itself.
60	func (b *binder) bindNode(ctx context.Context, node Node) hcl.Diagnostics {
61		if node.isBound() {
62			return nil
63		}
64		if node.isBinding() {
65			// We encountered the same node while binding its dependencies, so we have a circular reference.
66			// However we need to make an exception for nodes of type Component when
67			// - they are not self-referencing
68			// - the circular reference is only between other nodes of type Component
69			if !isComponent(node) || selfReferencingNode(node) {
70				// TODO(pdg): print better trace
71				rng := node.SyntaxNode().Range()
72				return hcl.Diagnostics{{
73					Severity: hcl.DiagError,
74					Summary:  "circular reference",
75					Subject:  &rng,
76				}}
77			}
78		}
79		node.markBinding()
80	
81		var diagnostics hcl.Diagnostics
82	
83		deps := b.getDependencies(node)
84		node.setDependencies(deps)
85	
86		// Bind any nodes this node depends on.
87		for _, dep := range deps {
88			if dep.isBinding() && mutuallyDependantComponents(node, dep) {
89				// We encountered a dependant node that is already being bound
90				// usually this is a circular reference, but we need to make an exception for nodes
91				// that are components and reference each other (mutually dependant components)
92				continue
93			}
94			diags := b.bindNode(ctx, dep)
95			diagnostics = append(diagnostics, diags...)
96		}
97	
98		switch node := node.(type) {
99		case *ConfigVariable:
100			diags := b.bindConfigVariable(node)
101			diagnostics = append(diagnostics, diags...)
102		case *LocalVariable:
103			diags := b.bindLocalVariable(node)
104			diagnostics = append(diagnostics, diags...)
105		case *Resource:
106			diags := b.bindResource(ctx, node)
107			diagnostics = append(diagnostics, diags...)
108		case *Component:
109			diags := b.bindComponent(node)
110			diagnostics = append(diagnostics, diags...)
111		case *OutputVariable:
112			diags := b.bindOutputVariable(node)
113			diagnostics = append(diagnostics, diags...)
114		case *PulumiBlock:
115			diags := b.bindPulumi(node)
116			diagnostics = append(diagnostics, diags...)
117		default:
118			contract.Failf("unexpected node of type %T (%v)", node, node.SyntaxNode().Range())
119		}
120	
121		node.markBound()
122		return diagnostics
123	}
124	
125	// getDependencies returns the dependencies for the given node.
126	func (b *binder) getDependencies(node Node) []Node {
127		depSet := codegen.Set{}
128		var deps []Node
129		diags := hclsyntax.VisitAll(node.SyntaxNode(), func(node hclsyntax.Node) hcl.Diagnostics {
130			var depName string
131			switch node := node.(type) {
132			case *hclsyntax.FunctionCallExpr:
133				// TODO(pdg): function scope binds tighter than "normal" scope
134				depName = node.Name
135			case *hclsyntax.ScopeTraversalExpr:
136				depName = node.Traversal.RootName()
137			default:
138				return nil
139			}
140	
141			// Missing reference errors will be issued during expression binding.
142			referent, _ := b.root.BindReference(depName)
143			if node, ok := referent.(Node); ok && !depSet.Has(node) {
144				depSet.Add(node)
145				deps = append(deps, node)
146			}
147			return nil
148		})
149		contract.Assertf(len(diags) == 0, "unexpected diagnostics: %v", diags)
150		return SourceOrderNodes(deps)
151	}
152	
153	func expressionIsLiteralNull(expr model.Expression) bool {
154		switch expr := expr.(type) {
155		case *model.LiteralValueExpression:
156			return expr.Value.IsNull()
157		default:
158			return false
159		}
160	}
161	
162	func (b *binder) bindConfigVariable(node *ConfigVariable) hcl.Diagnostics {
163		block, diagnostics := model.BindBlock(node.syntax, model.StaticScope(b.root), b.tokens, b.options.modelOptions()...)
164		if defaultValue, ok := block.Body.Attribute("default"); ok {
165			node.DefaultValue = defaultValue.Value
166			// when default is null and the type is not already optional
167			// turn the config type T into option(T)
168			if expressionIsLiteralNull(node.DefaultValue) && !model.IsOptionalType(node.typ) {
169				node.typ = model.NewOptionalType(node.typ)
170				node.Nullable = true
171			}
172	
173			if model.InputType(node.typ).ConversionFrom(node.DefaultValue.Type()) == model.NoConversion {
174				errorDiagnostic := model.ExprNotConvertible(model.InputType(node.typ), node.DefaultValue)
175				diagnostics = append(diagnostics, errorDiagnostic)
176			}
177		}
178	
179		if attr, ok := block.Body.Attribute(LogicalNamePropertyKey); ok {
180			logicalName, lDiags := getStringAttrValue(attr)
181			if lDiags != nil {
182				diagnostics = diagnostics.Append(lDiags)
183			} else {
184				node.logicalName = logicalName
185			}
186		}
187	
188		if descriptionAttr, ok := block.Body.Attribute("description"); ok {
189			description, diags := getStringAttrValue(descriptionAttr)
190			if diags != nil {
191				diagnostics = diagnostics.Append(diags)
192			} else {
193				node.Description = description
194			}
195		}
196	
197		if nullableAttr, ok := block.Body.Attribute("nullable"); ok {
198			nullable, diags := getBooleanAttributeValue(nullableAttr)
199			if diags != nil {
200				diagnostics = diagnostics.Append(diags)
201			} else {
202				node.Nullable = nullable
203			}
204		}
205	
206		if secretAttr, ok := block.Body.Attribute("secret"); ok {
207			secret, diags := getBooleanAttributeValue(secretAttr)
208			if diags != nil {
209				diagnostics = diagnostics.Append(diags)
210			} else {
211				node.Secret = secret
212			}
213		}
214	
215		if node.Secret {
216			node.typ = model.NewOutputType(node.typ)
217		}
218	
219		node.Definition = block
220		return diagnostics
221	}
222	
223	func (b *binder) bindLocalVariable(node *LocalVariable) hcl.Diagnostics {
224		attr, diagnostics := model.BindAttribute(node.syntax, b.root, b.tokens, b.options.modelOptions()...)
225		node.Definition = attr
226		return diagnostics
227	}
