// Hook represents a named resource lifecycle hook block in a PCL program. Hook blocks have a single
// label (the hook name) and define a command to run along with whether the hook runs on dry-runs.
type Hook struct {
	node

	syntax *hclsyntax.Block

	// The definition of the hook.
	Definition *model.Block

	// The command to run when the hook is invoked.
	Command model.Expression
	// Whether the hook should run during a dry-run (preview).
	OnDryRun model.Expression
}

// SyntaxNode returns the syntax node associated with the hook.
func (h *Hook) SyntaxNode() hclsyntax.Node {
	return h.syntax
}

func (h *Hook) Traverse(traverser hcl.Traverser) (model.Traversable, hcl.Diagnostics) {
	return model.StringType.Traverse(traverser)
}

func (h *Hook) VisitExpressions(pre, post model.ExpressionVisitor) hcl.Diagnostics {
	return model.VisitExpressions(h.Definition, pre, post)
}

// Name returns the lexical name of the hook.
func (h *Hook) Name() string {
	return h.syntax.Labels[0]
}

// Type returns the type of the hook.
func (h *Hook) Type() model.Type {
	return model.StringType
}
