// mutuallyDependantComponents returns true if the given nodes are components that reference each other.
func mutuallyDependantComponents(a Node, b Node) bool {
	return isComponent(a) &&
		isComponent(b) &&
		hasReferenceTo(a, b) &&
		hasReferenceTo(b, a) &&
