func hasErrorSummary(diags hcl.Diagnostics, summary string) bool {
	for _, d := range diags {
		if d.Severity == hcl.DiagError && d.Summary == summary {
			return true
		}
	}
	return false
}

func TestScratchHookBasic(t *testing.T) {
	t.Parallel()
	src := `
hook "foo" {
  command = ["echo", "hi", args.urn, args.id, args.name, args.type]
  onDryRun = true
}
`
	program, diags, err := ParseAndBindProgram(t, src, "program.pp")
	if err != nil {
		t.Fatalf("err: %v", err)
	}
	if diags.HasErrors() {
		t.Fatalf("unexpected diags: %v", diags)
	}
	if len(program.Hooks()) != 1 {
		t.Fatalf("expected 1 hook, got %d", len(program.Hooks()))
	}
}

func TestScratchHookArgsMapFields(t *testing.T) {
	t.Parallel()
	src := `
hook "foo" {
  command = [args.new_inputs["x"], args.old_inputs["y"], args.new_outputs["z"], args.old_outputs["w"]]
}
`
	_, diags, err := ParseAndBindProgram(t, src, "program.pp")
	if err != nil {
		t.Fatalf("err: %v", err)
	}
	if diags.HasErrors() {
		t.Fatalf("unexpected diags: %v", diags)
	}
}

func TestScratchHookUnknownAttr(t *testing.T) {
	t.Parallel()
	src := `
hook "foo" {
  command = ["echo"]
  bogus = 1
}
`
	_, diags, _ := ParseAndBindProgram(t, src, "program.pp")
	if !hasErrorSummary(diags, "unknown property 'bogus' among [command onDryRun]") {
		t.Fatalf("missing expected diag, got: %v", diags)
	}
}

