func TestScratchHookCommandComplexFails(t *testing.T) {
	t.Parallel()
	src := `
hook "foo" {
  command = [[], {}]
}
`
	_, diags, _ := ParseAndBindProgram(t, src, "program.pp")
	want := "cannot assign expression of type ((), {}) to location of type " +
		"list(output(string) | string) | output(list(string)): "
	if !hasErrorSummary(diags, want) {
		t.Fatalf("missing expected command diag, got: %v", diags)
	}
}

func TestScratchResourceHooksEvaluate(t *testing.T) {
	t.Parallel()
	src := `
hook "foo" {
  command = ["echo"]
}

resource "r" "random:index/randomPet:RandomPet" {
  options {
    hooks = {
      beforeCreate = [foo]
    }
  }
}
`
	program, diags, err := ParseAndBindProgram(t, src, "program.pp")
	if err != nil {
		t.Fatalf("err: %v", err)
	}
	if diags.HasErrors() {
		t.Fatalf("unexpected diags: %v", diags)
	}
	var resource *pcl.Resource
	for _, n := range program.Nodes {
		if r, ok := n.(*pcl.Resource); ok {
			resource = r
		}
	}
	if resource == nil || resource.Options == nil || resource.Options.Hooks == nil {
		t.Fatalf("no hooks expression set")
	}
	v, evalDiags := resource.Options.Hooks.Evaluate(&hcl.EvalContext{})
	if evalDiags.HasErrors() {
		t.Fatalf("eval diags: %v", evalDiags)
	}
	want := cty.ObjectVal(map[string]cty.Value{
		"beforeCreate": cty.TupleVal([]cty.Value{cty.StringVal("foo")}),
	})
	if !v.RawEquals(want) {
		t.Fatalf("got %#v want %#v", v, want)
	}
}

